// Turn `gh pr list` output into one item per closed redesign PR.
// Adds structured state the decider can use: whether a later PR with the same title replaced this one.
const prs = JSON.parse($input.first().json.stdout || '[]');
const redesignBranch = /^(redesign|rebuild|preview\/redesign)\//;
const redesign = prs.filter(p => redesignBranch.test(p.headRefName));

const styleOf = title => title.replace(/^(Monthly redesign|Full rebuild|Preview: Monthly redesign)\s*[:—-]\s*/i, '').split(' — ')[0].trim();

return redesign.map(p => {
  const later = redesign
    .filter(o => o.number !== p.number && styleOf(o.title) === styleOf(p.title) && o.createdAt > p.createdAt)
    .sort((a, b) => a.createdAt.localeCompare(b.createdAt))[0];
  return {
    json: {
      pr_number: p.number,
      title: p.title,
      style_name: styleOf(p.title),
      branch: p.headRefName,
      url: p.url,
      outcome: p.mergedAt ? 'merged' : 'rejected',
      closed_at: p.closedAt,
      changed_files: p.changedFiles,
      additions: p.additions,
      deletions: p.deletions,
      later_pr_same_style: later ? { number: later.number, outcome: later.mergedAt ? 'merged' : 'closed without merge' } : null,
    },
  };
});

// State in, typed questions out. The decider answers; the next node decides.
const pr = $('Only new PRs').item.json;
const fetched = JSON.parse($json.stdout || '{}');

// Feedback from the site owner only. Deploy bots (Cloudflare preview) comment on every PR
// and add nothing but input tokens, which cost about a minute per 1k on this CPU.
const REVIEWERS = ['sreeo'];
const feedback = [...(fetched.reviews || []), ...(fetched.comments || [])]
  .filter(c => REVIEWERS.includes(c.author) && c.body && c.body.trim())
  .map(c => ({ author: c.author, body: c.body.slice(0, 1500) }))
  .slice(0, 10);

const state = {
  pr: {
    number: pr.pr_number,
    title: pr.title,
    outcome: pr.outcome === 'merged' ? 'merged' : 'closed without merge',
    changed_files: pr.changed_files,
    additions: pr.additions,
    deletions: pr.deletions,
    files: fetched.files || [],
  },
  review_comments: feedback,
  later_pr_same_style: pr.later_pr_same_style,
};

const questions = pr.outcome === 'merged'
  ? {
      reception: {
        type: 'score',
        instructions: 'How positive was the reviewer about this redesign?',
        criteria: ['negative', 'mixed', 'positive'],
      },
    }
  : {
      reason: {
        type: 'choice',
        instructions: 'Why was this redesign pull request closed without merging?',
        criteria: {
          'pipeline-failure': 'The automation produced an empty or bogus change, not a real redesign',
          'superseded': 'A newer pull request replaced it',
          'test-run': 'A rehearsal or test run of the automation, never meant to merge',
          'broken-layout': 'Pages render broken: overlap, overflow, missing content',
          'unreadable': 'Text is hard to read: contrast, size, typography',
          'style-disliked': 'The reviewer did not want this visual style',
          'too-similar': 'Too close to an earlier design',
          'no-reason': 'Nothing in the state explains it',
        },
      },
      // One choice keeps only the main reason. A comment can give several, so every signal
      // the pipeline acts on gets its own yes/no question.
      says_too_similar: { type: 'noul', instructions: 'Does the review say the design was too close to, or a reskin of, an earlier design?' },
      says_quality_problem: { type: 'noul', instructions: 'Does the review say text was hard to read or pages rendered broken?' },
      avoid_style: { type: 'noul', instructions: 'Should future redesigns avoid this visual style?' },
    };

return {
  json: {
    ...pr,
    review_text: feedback.map(c => `${c.author}: ${c.body}`).join('\n---\n').slice(0, 4000),
    request: { state, questions },
  },
};

// The model gives probabilities. Code makes the call, with explicit thresholds.
const pr = $('Build typed questions').item.json;
const a = $json.answers || {};

// Style-level signals mean "don't pick this style again".
// Quality signals (unreadable, broken) become lessons for the implementer instead.
const MIN_P = 0.5;       // main reason must be at least this likely to count as known
const MIN_SIGNAL = 0.6;  // a yes/no signal must be at least this likely to act on it
const MIN_AVOID = 0.5;   // and the model must lean towards avoiding the style

const row = {
  pr_number: pr.pr_number,
  title: pr.title,
  style_name: pr.style_name,
  branch: pr.branch,
  url: pr.url,
  outcome: pr.outcome,
  closed_at: pr.closed_at,
  review_text: pr.review_text,
  reason: null,
  reason_confidence: null,
  reason_probs: null,
  avoid_prob: null,
  too_similar_prob: null,
  quality_problem_prob: null,
  reception: null,
  avoid: false,
  lesson: false,
  needs_review: false,
  model: $json.model || $json.x_model || null,
  latency_ms: $json.x_latency_ms ?? null,
  decided_at: new Date().toISOString(),
};

if (pr.outcome === 'merged') {
  row.reason = 'accepted';
  row.reception = a.reception?.score ?? null;
} else {
  const r = a.reason || {};
  row.reason = r.choice ?? null;
  row.reason_confidence = r.x_p_max ?? null;
  row.reason_probs = r.probabilities ? JSON.stringify(r.probabilities) : null;
  row.avoid_prob = a.avoid_style?.noul ?? null;
  row.too_similar_prob = a.says_too_similar?.noul ?? null;
  row.quality_problem_prob = a.says_quality_problem?.noul ?? null;
  const sure = (r.x_p_max ?? 0) >= MIN_P;
  const styleSignal = (row.too_similar_prob ?? 0) >= MIN_SIGNAL || (sure && row.reason === 'style-disliked');
  row.avoid = styleSignal && (row.avoid_prob ?? 0) >= MIN_AVOID;
  row.lesson = (row.quality_problem_prob ?? 0) >= MIN_SIGNAL;
  row.needs_review = !sure;
}

return { json: row };
